<?php
namespace davvag_events;

require_once dirname(__DIR__,2).'/lib/bootstrap.php';

final class GuestService extends Service {
    public function getGuests($req,$res) { return $this->run($req,$res,function($in){$e=Store::load($in['eventId']??'');Identity::authorize($e,Identity::actor(),'guests');return ['parties'=>$e['parties'],'guests'=>$e['guests'],'revision'=>$e['revision']];}); }
    public function postAddParty($req,$res) { return $this->run($req,$res,function($in){$a=Identity::actor();$r=Store::mutate($in['eventId']??'',$a,'guests',function(&$e)use($in){return Domain::addParty($e,$in);},$in['revision']??null);return ['party'=>$r['value'],'revision'=>$r['event']['revision']];},true); }
    public function postRespond($req,$res) { return $this->run($req,$res,function($in){$r=Store::mutate($in['eventId']??'',Identity::actor(),'guests',function(&$e)use($in){return Domain::rsvp($e,$in['partyId']??'',$in,true);},$in['revision']??null);return $r['value'];},true); }
    public function postRotateInvitation($req,$res) { return $this->run($req,$res,function($in){$r=Store::mutate($in['eventId']??'',Identity::actor(),'guests',function(&$e)use($in){$id=$in['partyId']??'';Domain::partyIndex($e,$id);foreach($e['tokens'] as &$t)if($t['scope']==='rsvp'&&$t['reference']===$id)$t['revoked']=true;unset($t);if(!empty($in['revokeOnly']))return ['revoked'=>true];$secret=Domain::issue($e,'rsvp',$id);return ['url'=>Support::publicUrl($e['id'],$secret),'credential'=>$secret,'warning'=>'This private link is shown once. Rotating invalidates previous invitation links.'];});return $r['value'];},true); }
    public function postPreviewImport($req,$res) { return $this->run($req,$res,function($in){$e=Store::load($in['eventId']??'');$a=Identity::actor();Identity::authorize($e,$a,'guests');$p=Csv::preview($e,$in['csv']??'',$in['duplicatePolicy']??'reject');$_SESSION['davvag_events_import'][$e['id']]=['hash'=>$p['hash'],'actor'=>$a['id'],'expires'=>time()+600];return $p;},true); }
    public function postApplyImport($req,$res) { return $this->run($req,$res,function($in){$a=Identity::actor();$saved=$_SESSION['davvag_events_import'][$in['eventId']??'']??null;$r=Store::mutate($in['eventId']??'',$a,'guests',function(&$e)use($in,$a,$saved){$p=Csv::preview($e,$in['csv']??'',$in['duplicatePolicy']??'reject');if(empty($in['confirmed'])||!$saved||$saved['actor']!==$a['id']||$saved['expires']<time()||!hash_equals($saved['hash'],$p['hash'])||!$p['valid'])Support::fail('CSV_PREVIEW','Review a fresh valid import preview before applying.',409);$n=0;foreach($p['rows'] as $r)if(!$r['skip']){Domain::addParty($e,$r['data']);$n++;}return ['imported'=>$n];});unset($_SESSION['davvag_events_import'][$in['eventId']]);return $r['value'];},true); }
    public function getExport($req,$res) { return $this->run($req,$res,function($in){$e=Store::load($in['eventId']??'');Identity::authorize($e,Identity::actor(),'reports');return ['filename'=>'event-attendees.csv','csv'=>Csv::export($e)];}); }
    public function postQueueInvitation($req,$res) { return $this->run($req,$res,function($in){if(!is_file(TENANT_RESOURCE_LOCATION.'/global/config/emailsmtp.conf'))Support::fail('SMTP_SETUP','Configure tenant SMTP before sending invitations.',503);Support::key();$r=Store::mutate($in['eventId']??'',Identity::actor(),'guests',function(&$e)use($in){$p=$e['parties'][Domain::partyIndex($e,$in['partyId']??'')];if(!$p['emailConsent']||!$p['email'])Support::fail('CONSENT','A valid email and explicit delivery consent are required.');Domain::publicView($e);$op=Support::text($in['operation']??'',80,true);foreach($e['jobs'] as $j)if($j['key']==='invite-'.$op)return ['queued'=>true];foreach($e['tokens'] as &$t)if($t['scope']==='rsvp'&&$t['reference']===$p['id'])$t['revoked']=true;unset($t);$secret=Domain::issue($e,'rsvp',$p['id']);Jobs::enqueue($e,'email',$p['id'],'invite-'.$op,['delivery'=>Support::encrypt(['url'=>Support::publicUrl($e['id'],$secret)])],Support::instant($in['runAt']??Support::now()));return ['queued'=>true];});return $r['value'];},true); }
}
